/*-
 * Finite field inversion.
 * Computed with Bernstein-Yang algorithm.
 * https://tches.iacr.org/index.php/TCHES/article/view/8298
 * Based on https://github.com/mit-plv/fiat-crypto/tree/master/inversion/c
 * NB: this is not a real fiat-crypto function, just named that way for consistency.
 */
static inline void fiat_brainpoolp512_inv(fe_t output, const fe_t t1) {
    int i;
    fe_t v1, r1, v2;
    limb_t *r2 = output;
    limb_t f1[LIMB_CNT + 1], g1[LIMB_CNT + 1], f2[LIMB_CNT + 1],
        g2[LIMB_CNT + 1];
    limb_t d2, d1 = 1;

    fe_copy(g1, t1);
    g1[LIMB_CNT] = 0;
    fe_copy(f1, const_psat);
    f1[LIMB_CNT] = 0;
    fe_copy(r1, const_one);
    fe_set_zero(v1);

    /* 1479 divstep iterations */
    for (i = 0; i < 739; i++) {
        fiat_brainpoolp512_divstep(&d2, f2, g2, v2, r2, d1, f1, g1, v1, r1);
        fiat_brainpoolp512_divstep(&d1, f1, g1, v1, r1, d2, f2, g2, v2, r2);
    }

    fiat_brainpoolp512_divstep(&d2, f2, g2, v2, r2, d1, f1, g1, v1, r1);
    fiat_brainpoolp512_opp(output, v2);
    fiat_brainpoolp512_selectznz(output, f2[LIMB_CNT] >> (LIMB_BITS - 1), v2,
                                   output);
    fiat_brainpoolp512_mul(output, output, const_divstep);
}

/*-
 * Q := 2P, both projective, Q and P same pointers OK
 * Autogenerated: op3/dbl_proj.op3
 * https://eprint.iacr.org/2015/1060 Alg 6
 * ASSERT: a = -3
 */
static inline void point_double(pt_prj_t *Q, const pt_prj_t *P) {
    /* temporary variables */
    fe_t t0, t1, t2, t3, t4;
    /* constants */
    const limb_t *b = const_b;
    /* set pointers for legacy curve arith */
    const limb_t *X = P->X;
    const limb_t *Y = P->Y;
    const limb_t *Z = P->Z;
    limb_t *X3 = Q->X;
    limb_t *Y3 = Q->Y;
    limb_t *Z3 = Q->Z;

    /* the curve arith formula */
    fiat_brainpoolp512_square(t0, X);
    fiat_brainpoolp512_square(t1, Y);
    fiat_brainpoolp512_square(t2, Z);
    fiat_brainpoolp512_mul(t3, X, Y);
    fiat_brainpoolp512_add(t3, t3, t3);
    fiat_brainpoolp512_mul(t4, Y, Z);
    fiat_brainpoolp512_mul(Z3, X, Z);
    fiat_brainpoolp512_add(Z3, Z3, Z3);
    fiat_brainpoolp512_mul(Y3, b, t2);
    fiat_brainpoolp512_sub(Y3, Y3, Z3);
    fiat_brainpoolp512_add(X3, Y3, Y3);
    fiat_brainpoolp512_add(Y3, X3, Y3);
    fiat_brainpoolp512_sub(X3, t1, Y3);
    fiat_brainpoolp512_add(Y3, t1, Y3);
    fiat_brainpoolp512_mul(Y3, X3, Y3);
    fiat_brainpoolp512_mul(X3, X3, t3);
    fiat_brainpoolp512_add(t3, t2, t2);
    fiat_brainpoolp512_add(t2, t2, t3);
    fiat_brainpoolp512_mul(Z3, b, Z3);
    fiat_brainpoolp512_sub(Z3, Z3, t2);
    fiat_brainpoolp512_sub(Z3, Z3, t0);
    fiat_brainpoolp512_add(t3, Z3, Z3);
    fiat_brainpoolp512_add(Z3, Z3, t3);
    fiat_brainpoolp512_add(t3, t0, t0);
    fiat_brainpoolp512_add(t0, t3, t0);
    fiat_brainpoolp512_sub(t0, t0, t2);
    fiat_brainpoolp512_mul(t0, t0, Z3);
    fiat_brainpoolp512_add(Y3, Y3, t0);
    fiat_brainpoolp512_add(t0, t4, t4);
    fiat_brainpoolp512_mul(Z3, t0, Z3);
    fiat_brainpoolp512_sub(X3, X3, Z3);
    fiat_brainpoolp512_mul(Z3, t0, t1);
    fiat_brainpoolp512_add(Z3, Z3, Z3);
    fiat_brainpoolp512_add(Z3, Z3, Z3);
}

/*-
 * R := Q + P where R and Q are projective, P affine.
 * R and Q same pointers OK
 * R and P same pointers not OK
 * Autogenerated: op3/add_mixed.op3
 * https://eprint.iacr.org/2015/1060 Alg 5
 * ASSERT: a = -3
 */
static inline void point_add_mixed(pt_prj_t *R, const pt_prj_t *Q,
                                   const pt_aff_t *P) {
    /* temporary variables */
    fe_t t0, t1, t2, t3, t4;
    /* constants */
    const limb_t *b = const_b;
    /* set pointers for legacy curve arith */
    const limb_t *X1 = Q->X;
    const limb_t *Y1 = Q->Y;
    const limb_t *Z1 = Q->Z;
    const limb_t *X2 = P->X;
    const limb_t *Y2 = P->Y;
    fe_t X3;
    fe_t Y3;
    fe_t Z3;
    limb_t nz;

    /* check P for affine inf */
    fiat_brainpoolp512_nonzero(&nz, P->Y);

    /* the curve arith formula */
    fiat_brainpoolp512_mul(t0, X1, X2);
    fiat_brainpoolp512_mul(t1, Y1, Y2);
    fiat_brainpoolp512_add(t3, X2, Y2);
    fiat_brainpoolp512_add(t4, X1, Y1);
    fiat_brainpoolp512_mul(t3, t3, t4);
    fiat_brainpoolp512_add(t4, t0, t1);
    fiat_brainpoolp512_sub(t3, t3, t4);
    fiat_brainpoolp512_mul(t4, Y2, Z1);
    fiat_brainpoolp512_add(t4, t4, Y1);
    fiat_brainpoolp512_mul(Y3, X2, Z1);
    fiat_brainpoolp512_add(Y3, Y3, X1);
    fiat_brainpoolp512_mul(Z3, b, Z1);
    fiat_brainpoolp512_sub(X3, Y3, Z3);
    fiat_brainpoolp512_add(Z3, X3, X3);
    fiat_brainpoolp512_add(X3, X3, Z3);
    fiat_brainpoolp512_sub(Z3, t1, X3);
    fiat_brainpoolp512_add(X3, t1, X3);
    fiat_brainpoolp512_mul(Y3, b, Y3);
    fiat_brainpoolp512_add(t1, Z1, Z1);
    fiat_brainpoolp512_add(t2, t1, Z1);
    fiat_brainpoolp512_sub(Y3, Y3, t2);
    fiat_brainpoolp512_sub(Y3, Y3, t0);
    fiat_brainpoolp512_add(t1, Y3, Y3);
    fiat_brainpoolp512_add(Y3, t1, Y3);
    fiat_brainpoolp512_add(t1, t0, t0);
    fiat_brainpoolp512_add(t0, t1, t0);
    fiat_brainpoolp512_sub(t0, t0, t2);
    fiat_brainpoolp512_mul(t1, t4, Y3);
    fiat_brainpoolp512_mul(t2, t0, Y3);
    fiat_brainpoolp512_mul(Y3, X3, Z3);
    fiat_brainpoolp512_add(Y3, Y3, t2);
    fiat_brainpoolp512_mul(X3, t3, X3);
    fiat_brainpoolp512_sub(X3, X3, t1);
    fiat_brainpoolp512_mul(Z3, t4, Z3);
    fiat_brainpoolp512_mul(t1, t3, t0);
    fiat_brainpoolp512_add(Z3, Z3, t1);

    /* if P is inf, throw all that away and take Q */
    fiat_brainpoolp512_selectznz(R->X, nz, Q->X, X3);
    fiat_brainpoolp512_selectznz(R->Y, nz, Q->Y, Y3);
    fiat_brainpoolp512_selectznz(R->Z, nz, Q->Z, Z3);
}

/*-
 * R := Q + P all projective.
 * R and Q same pointers OK
 * R and P same pointers not OK
 * Autogenerated: op3/add_proj.op3
 * https://eprint.iacr.org/2015/1060 Alg 4
 * ASSERT: a = -3
 */
static inline void point_add_proj(pt_prj_t *R, const pt_prj_t *Q,
                                  const pt_prj_t *P) {
    /* temporary variables */
    fe_t t0, t1, t2, t3, t4, t5;
    /* constants */
    const limb_t *b = const_b;
    /* set pointers for legacy curve arith */
    const limb_t *X1 = Q->X;
    const limb_t *Y1 = Q->Y;
    const limb_t *Z1 = Q->Z;
    const limb_t *X2 = P->X;
    const limb_t *Y2 = P->Y;
    const limb_t *Z2 = P->Z;
    limb_t *X3 = R->X;
    limb_t *Y3 = R->Y;
    limb_t *Z3 = R->Z;

    /* the curve arith formula */
    fiat_brainpoolp512_mul(t0, X1, X2);
    fiat_brainpoolp512_mul(t1, Y1, Y2);
    fiat_brainpoolp512_mul(t2, Z1, Z2);
    fiat_brainpoolp512_add(t3, X1, Y1);
    fiat_brainpoolp512_add(t4, X2, Y2);
    fiat_brainpoolp512_mul(t3, t3, t4);
    fiat_brainpoolp512_add(t4, t0, t1);
    fiat_brainpoolp512_sub(t3, t3, t4);
    fiat_brainpoolp512_add(t4, Y1, Z1);
    fiat_brainpoolp512_add(t5, Y2, Z2);
    fiat_brainpoolp512_mul(t4, t4, t5);
    fiat_brainpoolp512_add(t5, t1, t2);
    fiat_brainpoolp512_sub(t4, t4, t5);
    fiat_brainpoolp512_add(X3, X1, Z1);
    fiat_brainpoolp512_add(Y3, X2, Z2);
    fiat_brainpoolp512_mul(X3, X3, Y3);
    fiat_brainpoolp512_add(Y3, t0, t2);
    fiat_brainpoolp512_sub(Y3, X3, Y3);
    fiat_brainpoolp512_mul(Z3, b, t2);
    fiat_brainpoolp512_sub(X3, Y3, Z3);
    fiat_brainpoolp512_add(Z3, X3, X3);
    fiat_brainpoolp512_add(X3, X3, Z3);
    fiat_brainpoolp512_sub(Z3, t1, X3);
    fiat_brainpoolp512_add(X3, t1, X3);
    fiat_brainpoolp512_mul(Y3, b, Y3);
    fiat_brainpoolp512_add(t1, t2, t2);
    fiat_brainpoolp512_add(t2, t1, t2);
    fiat_brainpoolp512_sub(Y3, Y3, t2);
    fiat_brainpoolp512_sub(Y3, Y3, t0);
    fiat_brainpoolp512_add(t1, Y3, Y3);
    fiat_brainpoolp512_add(Y3, t1, Y3);
    fiat_brainpoolp512_add(t1, t0, t0);
    fiat_brainpoolp512_add(t0, t1, t0);
    fiat_brainpoolp512_sub(t0, t0, t2);
    fiat_brainpoolp512_mul(t1, t4, Y3);
    fiat_brainpoolp512_mul(t2, t0, Y3);
    fiat_brainpoolp512_mul(Y3, X3, Z3);
    fiat_brainpoolp512_add(Y3, Y3, t2);
    fiat_brainpoolp512_mul(X3, t3, X3);
    fiat_brainpoolp512_sub(X3, X3, t1);
    fiat_brainpoolp512_mul(Z3, t4, Z3);
    fiat_brainpoolp512_mul(t1, t3, t0);
    fiat_brainpoolp512_add(Z3, Z3, t1);
}

/* constants */
#define RADIX 5
#define DRADIX (1 << RADIX)
#define DRADIX_WNAF ((DRADIX) << 1)

/*-
 * precomp for wnaf scalar multiplication:
 * precomp[0] = 1P
 * precomp[1] = 3P
 * precomp[2] = 5P
 * precomp[3] = 7P
 * precomp[4] = 9P
 * ...
 */
static inline void precomp_wnaf(pt_prj_t precomp[DRADIX / 2],
                                const pt_aff_t *P) {
    int i;

    fe_copy(precomp[0].X, P->X);
    fe_copy(precomp[0].Y, P->Y);
    fe_copy(precomp[0].Z, const_one);
    point_double(&precomp[DRADIX / 2 - 1], &precomp[0]);

    for (i = 1; i < DRADIX / 2; i++)
        point_add_proj(&precomp[i], &precomp[DRADIX / 2 - 1], &precomp[i - 1]);
}

/* fetch a scalar bit */
static inline int scalar_get_bit(const unsigned char in[64], int idx) {
    int widx, rshift;

    widx = idx >> 3;
    rshift = idx & 0x7;

    if (idx < 0 || widx >= 64) return 0;

    return (in[widx] >> rshift) & 0x1;
}

/*-
 * Compute "regular" wnaf representation of a scalar.
 * See "Exponent Recoding and Regular Exponentiation Algorithms",
 * Tunstall et al., AfricaCrypt 2009, Alg 6.
 * It forces an odd scalar and outputs digits in
 * {\pm 1, \pm 3, \pm 5, \pm 7, \pm 9, ...}
 * i.e. signed odd digits with _no zeroes_ -- that makes it "regular".
 */
static inline void scalar_rwnaf(int8_t out[103], const unsigned char in[64]) {
    int i;
    int8_t window, d;

    window = (in[0] & (DRADIX_WNAF - 1)) | 1;
    for (i = 0; i < 102; i++) {
        d = (window & (DRADIX_WNAF - 1)) - DRADIX;
        out[i] = d;
        window = (window - d) >> RADIX;
        window += scalar_get_bit(in, (i + 1) * RADIX + 1) << 1;
        window += scalar_get_bit(in, (i + 1) * RADIX + 2) << 2;
        window += scalar_get_bit(in, (i + 1) * RADIX + 3) << 3;
        window += scalar_get_bit(in, (i + 1) * RADIX + 4) << 4;
        window += scalar_get_bit(in, (i + 1) * RADIX + 5) << 5;
    }
    out[i] = window;
}

/*-
 * Compute "textbook" wnaf representation of a scalar.
 * NB: not constant time
 */
static inline void scalar_wnaf(int8_t out[513], const unsigned char in[64]) {
    int i;
    int8_t window, d;

    window = in[0] & (DRADIX_WNAF - 1);
    for (i = 0; i < 513; i++) {
        d = 0;
        if ((window & 1) && ((d = window & (DRADIX_WNAF - 1)) & DRADIX))
            d -= DRADIX_WNAF;
        out[i] = d;
        window = (window - d) >> 1;
        window += scalar_get_bit(in, i + 1 + RADIX) << RADIX;
    }
}

/*-
 * Simultaneous scalar multiplication: interleaved "textbook" wnaf.
 * NB: not constant time
 */
static inline void var_smul_wnaf_two(pt_aff_t *out, const unsigned char a[64],
                                     const unsigned char b[64],
                                     const pt_aff_t *P) {
    int i, d, is_neg, is_inf = 1, flipped = 0;
    int8_t anaf[513] = {0};
    int8_t bnaf[513] = {0};
    pt_prj_t Q = {{0}, {0}, {0}};
    pt_prj_t precomp[DRADIX / 2];

    precomp_wnaf(precomp, P);
    scalar_wnaf(anaf, a);
    scalar_wnaf(bnaf, b);

    for (i = 512; i >= 0; i--) {
        if (!is_inf) point_double(&Q, &Q);
        if ((d = bnaf[i])) {
            if ((is_neg = d < 0) != flipped) {
                fiat_brainpoolp512_opp(Q.Y, Q.Y);
                flipped ^= 1;
            }
            d = (is_neg) ? (-d - 1) >> 1 : (d - 1) >> 1;
            if (is_inf) {
                /* initialize accumulator */
                fe_copy(Q.X, &precomp[d].X);
                fe_copy(Q.Y, &precomp[d].Y);
                fe_copy(Q.Z, &precomp[d].Z);
                is_inf = 0;
            } else
                point_add_proj(&Q, &Q, &precomp[d]);
        }
        if ((d = anaf[i])) {
            if ((is_neg = d < 0) != flipped) {
                fiat_brainpoolp512_opp(Q.Y, Q.Y);
                flipped ^= 1;
            }
            d = (is_neg) ? (-d - 1) >> 1 : (d - 1) >> 1;
            if (is_inf) {
                /* initialize accumulator */
                fe_copy(Q.X, &lut_cmb[0][d].X);
                fe_copy(Q.Y, &lut_cmb[0][d].Y);
                fe_copy(Q.Z, const_one);
                is_inf = 0;
            } else
                point_add_mixed(&Q, &Q, &lut_cmb[0][d]);
        }
    }

    if (is_inf) {
        /* initialize accumulator to inf: all-zero scalars */
        fe_set_zero(Q.X);
        fe_copy(Q.Y, const_one);
        fe_set_zero(Q.Z);
    }

    if (flipped) {
        /* correct sign */
        fiat_brainpoolp512_opp(Q.Y, Q.Y);
    }

    /* convert to affine -- NB depends on coordinate system */
    fiat_brainpoolp512_inv(Q.Z, Q.Z);
    fiat_brainpoolp512_mul(out->X, Q.X, Q.Z);
    fiat_brainpoolp512_mul(out->Y, Q.Y, Q.Z);
}

/*-
 * Variable point scalar multiplication with "regular" wnaf.
 * Here "regular" means _no zeroes_, so the sequence of
 * EC arithmetic ops is fixed.
 */
static inline void var_smul_rwnaf(pt_aff_t *out, const unsigned char scalar[64],
                                  const pt_aff_t *P) {
    int i, j, d, diff, is_neg;
    int8_t rnaf[103] = {0};
    pt_prj_t Q = {{0}, {0}, {0}}, lut = {{0}, {0}, {0}};
    pt_prj_t precomp[DRADIX / 2];

    precomp_wnaf(precomp, P);
    scalar_rwnaf(rnaf, scalar);

#if defined(_MSC_VER)
    /* result still unsigned: yes we know */
#pragma warning(push)
#pragma warning(disable : 4146)
#endif

    /* initialize accumulator to high digit */
    d = (rnaf[102] - 1) >> 1;
    for (j = 0; j < DRADIX / 2; j++) {
        diff = (1 - (-(d ^ j) >> (8 * sizeof(int) - 1))) & 1;
        fiat_brainpoolp512_selectznz(Q.X, diff, Q.X, precomp[j].X);
        fiat_brainpoolp512_selectznz(Q.Y, diff, Q.Y, precomp[j].Y);
        fiat_brainpoolp512_selectznz(Q.Z, diff, Q.Z, precomp[j].Z);
    }

    for (i = 101; i >= 0; i--) {
        for (j = 0; j < RADIX; j++) point_double(&Q, &Q);
        d = rnaf[i];
        /* is_neg = (d < 0) ? 1 : 0 */
        is_neg = (d >> (8 * sizeof(int) - 1)) & 1;
        /* d = abs(d) */
        d = (d ^ -is_neg) + is_neg;
        d = (d - 1) >> 1;
        for (j = 0; j < DRADIX / 2; j++) {
            diff = (1 - (-(d ^ j) >> (8 * sizeof(int) - 1))) & 1;
            fiat_brainpoolp512_selectznz(lut.X, diff, lut.X, precomp[j].X);
            fiat_brainpoolp512_selectznz(lut.Y, diff, lut.Y, precomp[j].Y);
            fiat_brainpoolp512_selectznz(lut.Z, diff, lut.Z, precomp[j].Z);
        }
        /* negate lut point if digit is negative */
        fiat_brainpoolp512_opp(out->Y, lut.Y);
        fiat_brainpoolp512_selectznz(lut.Y, is_neg, lut.Y, out->Y);
        point_add_proj(&Q, &Q, &lut);
    }

#if defined(_MSC_VER)
#pragma warning(pop)
#endif

    /* conditionally subtract P if the scalar was even */
    fe_copy(lut.X, precomp[0].X);
    fiat_brainpoolp512_opp(lut.Y, precomp[0].Y);
    fe_copy(lut.Z, precomp[0].Z);
    point_add_proj(&lut, &lut, &Q);
    fiat_brainpoolp512_selectznz(Q.X, scalar[0] & 1, lut.X, Q.X);
    fiat_brainpoolp512_selectznz(Q.Y, scalar[0] & 1, lut.Y, Q.Y);
    fiat_brainpoolp512_selectznz(Q.Z, scalar[0] & 1, lut.Z, Q.Z);

    /* convert to affine -- NB depends on coordinate system */
    fiat_brainpoolp512_inv(Q.Z, Q.Z);
    fiat_brainpoolp512_mul(out->X, Q.X, Q.Z);
    fiat_brainpoolp512_mul(out->Y, Q.Y, Q.Z);
}

/*-
 * Fixed scalar multiplication: comb with interleaving.
 */
static inline void fixed_smul_cmb(pt_aff_t *out,
                                  const unsigned char scalar[64]) {
    int i, j, k, d, diff, is_neg = 0;
    int8_t rnaf[103] = {0};
    pt_prj_t Q = {{0}, {0}, {0}}, R = {{0}, {0}, {0}};
    pt_aff_t lut = {{0}, {0}};

    scalar_rwnaf(rnaf, scalar);

    /* initalize accumulator to inf */
    fe_set_zero(Q.X);
    fe_copy(Q.Y, const_one);
    fe_set_zero(Q.Z);

#if defined(_MSC_VER)
    /* result still unsigned: yes we know */
#pragma warning(push)
#pragma warning(disable : 4146)
#endif

    for (i = 7; i >= 0; i--) {
        for (j = 0; i != 7 && j < RADIX; j++) point_double(&Q, &Q);
        for (j = 0; j < 14; j++) {
            if (j * 8 + i > 102) continue;
            d = rnaf[j * 8 + i];
            /* is_neg = (d < 0) ? 1 : 0 */
            is_neg = (d >> (8 * sizeof(int) - 1)) & 1;
            /* d = abs(d) */
            d = (d ^ -is_neg) + is_neg;
            d = (d - 1) >> 1;
            for (k = 0; k < DRADIX / 2; k++) {
                diff = (1 - (-(d ^ k) >> (8 * sizeof(int) - 1))) & 1;
                fiat_brainpoolp512_selectznz(lut.X, diff, lut.X,
                                               lut_cmb[j][k].X);
                fiat_brainpoolp512_selectznz(lut.Y, diff, lut.Y,
                                               lut_cmb[j][k].Y);
            }
            /* negate lut point if digit is negative */
            fiat_brainpoolp512_opp(out->Y, lut.Y);
            fiat_brainpoolp512_selectznz(lut.Y, is_neg, lut.Y, out->Y);
            point_add_mixed(&Q, &Q, &lut);
        }
    }

#if defined(_MSC_VER)
#pragma warning(pop)
#endif

    /* conditionally subtract P if the scalar was even */
    fe_copy(lut.X, lut_cmb[0][0].X);
    fiat_brainpoolp512_opp(lut.Y, lut_cmb[0][0].Y);
    point_add_mixed(&R, &Q, &lut);
    fiat_brainpoolp512_selectznz(Q.X, scalar[0] & 1, R.X, Q.X);
    fiat_brainpoolp512_selectznz(Q.Y, scalar[0] & 1, R.Y, Q.Y);
    fiat_brainpoolp512_selectznz(Q.Z, scalar[0] & 1, R.Z, Q.Z);

    /* convert to affine -- NB depends on coordinate system */
    fiat_brainpoolp512_inv(Q.Z, Q.Z);
    fiat_brainpoolp512_mul(out->X, Q.X, Q.Z);
    fiat_brainpoolp512_mul(out->Y, Q.Y, Q.Z);
}

/*-
 * Wrapper: simultaneous scalar mutiplication.
 * outx, outy := a * G + b * P
 * where P = (inx, iny).
 * Everything is LE byte ordering.
 */
static inline
    void
    point_mul_two_brainpoolp512(unsigned char outx[64],
                                  unsigned char outy[64],
                                  const unsigned char a[64],
                                  const unsigned char b[64],
                                  const unsigned char inx[64],
                                  const unsigned char iny[64]) {
    pt_aff_t P;

    fiat_brainpoolp512_from_bytes(P.X, inx);
    fiat_brainpoolp512_from_bytes(P.Y, iny);
    fiat_brainpoolp512_to_montgomery(P.X, P.X);
    fiat_brainpoolp512_to_montgomery(P.Y, P.Y);
    /* simultaneous scalar multiplication */
    var_smul_wnaf_two(&P, a, b, &P);

    fiat_brainpoolp512_from_montgomery(P.X, P.X);
    fiat_brainpoolp512_from_montgomery(P.Y, P.Y);
    fiat_brainpoolp512_to_bytes(outx, P.X);
    fiat_brainpoolp512_to_bytes(outy, P.Y);
}

/*-
 * Wrapper: fixed scalar mutiplication.
 * outx, outy := scalar * G
 * Everything is LE byte ordering.
 */
static inline
    void
    point_mul_g_brainpoolp512(unsigned char outx[64], unsigned char outy[64],
                                const unsigned char scalar[64]) {
    pt_aff_t P;

    /* fixed scmul function */
    fixed_smul_cmb(&P, scalar);
    fiat_brainpoolp512_from_montgomery(P.X, P.X);
    fiat_brainpoolp512_from_montgomery(P.Y, P.Y);
    fiat_brainpoolp512_to_bytes(outx, P.X);
    fiat_brainpoolp512_to_bytes(outy, P.Y);
}

/*-
 * Wrapper: variable point scalar mutiplication.
 * outx, outy := scalar * P
 * where P = (inx, iny).
 * Everything is LE byte ordering.
 */
static inline
    void
    point_mul_brainpoolp512(unsigned char outx[64], unsigned char outy[64],
                              const unsigned char scalar[64],
                              const unsigned char inx[64],
                              const unsigned char iny[64]) {
    pt_aff_t P;

    fiat_brainpoolp512_from_bytes(P.X, inx);
    fiat_brainpoolp512_from_bytes(P.Y, iny);
    fiat_brainpoolp512_to_montgomery(P.X, P.X);
    fiat_brainpoolp512_to_montgomery(P.Y, P.Y);
    /* var scmul function */
    var_smul_rwnaf(&P, scalar, &P);
    fiat_brainpoolp512_from_montgomery(P.X, P.X);
    fiat_brainpoolp512_from_montgomery(P.Y, P.Y);
    fiat_brainpoolp512_to_bytes(outx, P.X);
    fiat_brainpoolp512_to_bytes(outy, P.Y);
}




